def start_listing_periods(apps, schema_editor):
    """Give live products a listing period starting now.

    Every existing seller starts on Garazna, so these products expire 30 days
    after this migration runs. listed_at keeps the creation date, so older
    products don't use up this month's listing slots.
    """
    Product = apps.get_model("products", "Product")
    expires_at = timezone.now() + timedelta(days=30)
    for product in Product.objects.filter(status="published"):
        product.listed_at = product.created_at
        product.expires_at = expires_at
        product.save(update_fields=["listed_at", "expires_at"])


